{{(() => {
  const who = MerchantSelect.selectedOptionValue && MerchantSelect.selectedOptionValue !== 'all' ? (MerchantSelect.selectedOptionLabel || '') : null;
  const e = (n) => (Number(n) || 0).toFixed(2) + ' €';
  const last = appsmith.store.last_payout_id ? `\nПоследно изплащане: ${appsmith.store.last_payout_id}` : '';
  if (!who) return 'Изплащане: избери клиент, за да видиш какво му дължим.';
  const p = GetPendingPayout.data;
  if (!p || !p.totals) return `Изплащане на ${who}: изчислява се…`;
  const t = p.totals;
  if (!t.orders) return `Няма неизплатени поръчки за ${who}.${last}`;
  return `Дължим на ${who}: ${e(t.owed)} по ${t.orders} ${t.orders === 1 ? 'поръчка' : 'поръчки'}
Събрано ${e(t.collected)} (в брой ${e(t.cash)}, с карта ${e(t.card)}) − наши ${e(t.revenue)}${last}`;
})()}}
